def main():
    t0 = time.time()
    per_agent = {}
    for agent in os.listdir(MEMORY):
        ap = os.path.join(MEMORY, agent)
        if not os.path.isdir(ap):
            continue
        counter = Counter()
        nfiles = 0
        for dirpath, _, filenames in os.walk(ap):
            for fn in filenames:
                if not fn.endswith(".md"):
                    continue
                nfiles += 1
                text = open(os.path.join(dirpath, fn), encoding="utf-8", errors="replace").read()
                counter.update(w.lower() for w in WORD_RE.findall(text) if w.lower() not in STOP)
        if nfiles:
            per_agent[agent] = {"files": nfiles, "top": counter.most_common(15)}
    hot_topics = Counter()
    for a in per_agent.values():
        for t, c in a["top"]:
            hot_topics[t] += c
    all_terms = set(hot_topics)
    lines = ["# Topic Heatmap (knowledge hot/cold)", "",
             f"Generated {time.strftime('%Y-%m-%d %H:%M:%S')} | build {time.time()-t0:.2f}s", "",
             "## HOT topics (most cited across agent memory)", ""]
    for t, c in hot_topics.most_common(25):
        lines.append(f"- {t}: {c}")
    cold = [a for a, v in per_agent.items() if sum(c for _, c in v["top"]) < 40]
    lines += ["", "## COLD agents (low citation mass - review/merge candidates)", ""]
    lines += [f"- {a}: {per_agent[a]['files']} files, mass={sum(c for _, c in per_agent[a]['top'])}" for a in cold] or ["- (none: all agents active)"]
    out_md = os.path.join(HERE, "topic-heatmap.md")
    open(out_md, "w", encoding="utf-8").write("\n".join(lines))
    json.dump({"generated": time.strftime("%Y-%m-%d %H:%M:%S"), "hot": hot_topics.most_common(25),
               "per_agent": {k: v["top"] for k, v in per_agent.items()}, "cold": cold},
              open(os.path.join(HERE, "topic-heatmap.json"), "w", encoding="utf-8"), indent=1)
    print(f"agents={len(per_agent)} hot_terms={len(all_terms)} cold_agents={len(cold)} build={time.time()-t0:.2f}s")

if __name__ == "__main__":
    main()
